package me.cryo.zombierool.block.system;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.block.state.properties.IntegerProperty;
import net.minecraft.world.phys.*;
import net.minecraft.world.phys.shapes.*;

/** A complete item, with ordinary block cells providing exact collision and chunk culling. */
public final class LargeFurnitureBlock extends FurnitureSystem.FurnitureBlock {
    public static final Map<String,int[]> SIZES=Map.ofEntries(Map.entry("dumpster",new int[]{3,3,2}),Map.entry("locker",new int[]{1,2,1}),Map.entry("filing_cabinet",new int[]{1,2,1}),Map.entry("medical_cabinet",new int[]{1,2,1}),Map.entry("display_fridge",new int[]{1,2,1}),Map.entry("industrial_shelf",new int[]{2,2,1}),Map.entry("desk",new int[]{2,1,1}),Map.entry("workbench",new int[]{2,1,1}),Map.entry("control_console",new int[]{2,1,1}),Map.entry("hotel_dresser",new int[]{2,1,1}),Map.entry("wow_tavern_table",new int[]{2,1,1}),Map.entry("wow_tavern_bench",new int[]{2,1,1}),Map.entry("wow_weapon_rack",new int[]{1,2,1}),Map.entry("wow_alchemy_table",new int[]{2,1,1}),Map.entry("flag_france",new int[]{2,3,1}),Map.entry("wall_standard_france",new int[]{1,2,1}),Map.entry("flag_united_kingdom",new int[]{2,3,1}),Map.entry("wall_standard_united_kingdom",new int[]{1,2,1}),Map.entry("flag_germany_historical",new int[]{2,3,1}),Map.entry("wall_standard_germany_historical",new int[]{1,2,1}),Map.entry("flag_soviet_union",new int[]{2,3,1}),Map.entry("wall_standard_soviet_union",new int[]{1,2,1}),Map.entry("flag_japan",new int[]{2,3,1}),Map.entry("wall_standard_japan",new int[]{1,2,1}),Map.entry("flag_usa",new int[]{2,3,1}),Map.entry("wall_standard_usa",new int[]{1,2,1}),Map.entry("flag_russia",new int[]{2,3,1}),Map.entry("wall_standard_russia",new int[]{1,2,1}),Map.entry("flag_germany",new int[]{2,3,1}),Map.entry("wall_standard_germany",new int[]{1,2,1}),Map.entry("flag_cuba",new int[]{2,3,1}),Map.entry("wall_standard_cuba",new int[]{1,2,1}),Map.entry("flag_lordaeron",new int[]{2,3,1}),Map.entry("wall_standard_lordaeron",new int[]{1,2,1}),Map.entry("flag_scourge",new int[]{2,3,1}),Map.entry("wall_standard_scourge",new int[]{1,2,1}),Map.entry("flag_stormwind",new int[]{2,3,1}),Map.entry("wall_standard_stormwind",new int[]{1,2,1}),Map.entry("flag_orgrimmar",new int[]{2,3,1}),Map.entry("wall_standard_orgrimmar",new int[]{1,2,1}),Map.entry("flag_burning_legion",new int[]{2,3,1}),Map.entry("wall_standard_burning_legion",new int[]{1,2,1}),Map.entry("flag_scarlet_crusade",new int[]{2,3,1}),Map.entry("wall_standard_scarlet_crusade",new int[]{1,2,1}),Map.entry("flag_forsaken",new int[]{2,3,1}),Map.entry("wall_standard_forsaken",new int[]{1,2,1}),Map.entry("flag_japan_empire",new int[]{2,3,1}),Map.entry("wall_standard_japan_empire",new int[]{1,2,1}));
    public static final IntegerProperty PART=IntegerProperty.create("part",0,17);
    private static final ThreadLocal<Boolean> REMOVING=ThreadLocal.withInitial(()->false);
    private final Map<Integer,VoxelShape> pieces=new HashMap<>();
    public final int partCount;
    public LargeFurnitureBlock(String id){super(id);var size=SIZES.get(id);partCount=size[0]*size[1]*size[2];registerDefaultState(defaultBlockState().setValue(PART,0));
        for(int i=0;i<partCount;i++)for(var face:Direction.Plane.HORIZONTAL){var result=Shapes.empty();for(var original:FurnitureSystem.boxes(id+(i==0?"":"_part_"+i))){var box=original;int turns=face==Direction.NORTH?0:face==Direction.EAST?1:face==Direction.SOUTH?2:3;for(int turn=0;turn<turns;turn++)box=new AABB(1-box.maxZ,box.minY,box.minX,1-box.minZ,box.maxY,box.maxX);result=Shapes.or(result,Shapes.create(box));}pieces.put(i*4+face.get2DDataValue(),result.optimize());}}
    @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> builder){super.createBlockStateDefinition(builder);builder.add(PART);}
    public BlockPos offset(int index,Direction face){var size=SIZES.get(model);int x=index%size[0],y=index/size[0]%size[1],z=index/(size[0]*size[1]);return switch(face){case EAST->new BlockPos(-z,y,x);case SOUTH->new BlockPos(-x,y,-z);case WEST->new BlockPos(z,y,-x);default->new BlockPos(x,y,z);};}
    @Override public VoxelShape getShape(BlockState state,BlockGetter level,BlockPos pos,CollisionContext context){return pieces.get(Math.min(partCount-1,state.getValue(PART))*4+state.getValue(FACING).get2DDataValue());}
    @Override public VoxelShape wholeShape(BlockState state){var shape=Shapes.empty();for(int i=0;i<partCount;i++){var off=offset(i,state.getValue(FACING));shape=Shapes.or(shape,getShape(state.setValue(PART,i),null,BlockPos.ZERO,CollisionContext.empty()).move(off.getX(),off.getY(),off.getZ()));}return shape;}
    @Override public BlockState getStateForPlacement(BlockPlaceContext context){var state=super.getStateForPlacement(context);for(int i=0;i<partCount;i++){var pos=context.getClickedPos().offset(offset(i,state.getValue(FACING)));if(!context.getLevel().isInWorldBounds(pos)||i>0&&!context.getLevel().getBlockState(pos).isAir())return null;}return state;}
    @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,net.minecraft.world.entity.LivingEntity placer,ItemStack stack){if(!level.isClientSide)for(int i=1;i<partCount;i++)level.setBlock(pos.offset(offset(i,state.getValue(FACING))),state.setValue(PART,i),3);}
    @Override public void onRemove(BlockState state,Level level,BlockPos pos,BlockState next,boolean moving){if(state.getBlock()!=next.getBlock()&&!REMOVING.get()){REMOVING.set(true);try{var root=pos.subtract(offset(state.getValue(PART),state.getValue(FACING)));for(int i=0;i<partCount;i++){var at=root.offset(offset(i,state.getValue(FACING)));var other=level.getBlockState(at);if(!at.equals(pos)&&other.is(this)&&other.getValue(PART)==i&&other.getValue(FACING)==state.getValue(FACING))level.removeBlock(at,false);}}finally{REMOVING.remove();}}super.onRemove(state,level,pos,next,moving);}
}
